// Bounded, versioned, byte-exact archives; corruption never permits cleanup.
import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import zlib from 'node:zlib';import {createGeneration,requiredRecords,record,seal,verifyBundle,readSealedRecord,cleanup} from './agent-benchmark-results.mjs';
const [out]=process.argv.slice(2);assert(out&&path.isAbsolute(out)&&!fs.existsSync(out));fs.mkdirSync(out);let checks=0;const check=(v,m)=>{assert(v,m);checks++;};
function generation(name){const root=path.join(out,name);createGeneration(root,'bundle-'+name);for(const k of requiredRecords)record(root,k,{kind:k,paid_solver_calls:0});return root;}
const root=generation('roundtrip'),raw=Buffer.alloc(3*1024*1024+17);for(let i=0;i<raw.length;i++)raw[i]=i%251;fs.writeFileSync(path.join(root,'records','binary.bin'),raw);fs.writeFileSync(path.join(root,'records','empty.bin'),'');const bundle=seal(root,{formatVersion:2});check(bundle.lossless,'v2 verified');check(readSealedRecord(root,'binary.bin').equals(raw),'multiframe binary exact');check(readSealedRecord(root,'empty.bin').length===0,'empty exact');const lines=zlib.gunzipSync(fs.readFileSync(path.join(root,'results.json.gz'))).toString('utf8').trim().split('\n').map(x=>JSON.parse(x));check(lines[0].version===2&&lines.at(-1).type==='end','standard concatenated gzip JSONL');cleanup(root);check(readSealedRecord(root,'binary.bin').equals(raw),'read after cleanup');
const old=generation('legacy');seal(old,{formatVersion:1});check(JSON.parse(zlib.gunzipSync(fs.readFileSync(path.join(old,'results.json.gz')))).version===1,'v1 remains readable');check(verifyBundle(old).lossless,'legacy verifier');
const corrupt=generation('corrupt');seal(corrupt,{formatVersion:2});const f=path.join(corrupt,'results.json.gz'),b=fs.readFileSync(f);b[Math.floor(b.length/2)]^=1;fs.writeFileSync(f,b);assert.throws(()=>verifyBundle(corrupt),/corruption/);checks++;assert.throws(()=>cleanup(corrupt),/corruption/);checks++;fs.writeFileSync(path.join(out,'receipt.json'),JSON.stringify({ok:true,checks,skipped:0,bundle,paid_solver_calls:0},null,2));console.log(JSON.stringify({ok:true,checks,skipped:0,paid_solver_calls:0}));
